main.script:
document.addEventListener("DOMContentLoaded", () => {
    const root = document.getElementById("sunapp_saas_progress");
    const title = document.getElementById("sunapp_saas_title");
    const message = document.getElementById("sunapp_saas_message");
    const spinner = document.getElementById("sunapp_saas_spinner");
    const progressBar = document.getElementById("sunapp_saas_progress_bar");
    const errorBox = document.getElementById("sunapp_saas_error");
    const existingCustomer = document.getElementById("sunapp_existing_customer");
    const actions = document.getElementById("sunapp_saas_actions");
    const instanceLink = document.getElementById("sunapp_instance_link");
    const credentialsLink = document.getElementById("sunapp_credentials_link");
    let attempts = 0;

    function updateStep(name, completed) {
        const element = document.getElementById(`step_${name}`);
        element.textContent = completed ? "Terminé" : "En attente";
        element.classList.toggle("text-success", completed);
        element.classList.toggle("text-muted", !completed);
    }

    async function refreshStatus() {
        attempts += 1;
        try {
            const response = await fetch(root.dataset.statusUrl, {
                cache: "no-store",
                headers: {"Accept": "application/json"},
            });
            const result = await response.json();
            progressBar.style.width = `${result.progress || 20}%`;
            progressBar.setAttribute("aria-valuenow", result.progress || 20);
            Object.entries(result.steps || {}).forEach(([name, completed]) => {
                updateStep(name, completed);
            });
            existingCustomer.classList.toggle("d-none", !result.customer_existing);
            if (result.error) {
                errorBox.textContent = result.error;
                errorBox.classList.remove("d-none");
            } else {
                errorBox.classList.add("d-none");
            }
            if (result.status === "ready") {
                spinner.classList.add("d-none");
                progressBar.classList.remove("progress-bar-animated");
                title.textContent = "Votre espace SunApp est prêt";
                message.textContent = "Vos accès sont disponibles et vous ont également été transmis par e-mail.";
                instanceLink.href = result.instance_url;
                credentialsLink.href = result.download_url;
                actions.classList.remove("d-none");
                actions.classList.add("d-flex");
                return;
            }
        } catch (error) {
            // A temporary network error must not interrupt status polling.
        }
        if (attempts === 100) {
            message.textContent = "La préparation prend un peu plus de temps. Vous recevrez vos accès par e-mail dès qu'elle sera terminée.";
        }
        window.setTimeout(refreshStatus, 5000);
    }

    window.setTimeout(refreshStatus, 2000);
});
